// basic usage
ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
defer cancel()
stream, err := client.StartStream(ctx, req)
if err != nil { log.Fatal(err) }
for {
  chunk, err := stream.Recv()
  if err != nil {
    if err == io.EOF { break }
    log.Printf("stream error: %v", err)
    break
  }
  process(chunk)
}
stream.Close()

// opt-in resume example
if stream.ResumeToken() != "" {
  resumed, err := client.ResumeFrom(ctx, stream.ResumeToken())
  // handle resumed stream
}
